  return try await api.search(q)
}

// Managing an unstructured Task as state
@MainActor
@Observable
final class SearchModel {
  var results: [SearchHit] = []
  private var task: Task<Void, Never>?

  func search(_ q: String) {
    task?.cancel()               // the previous keystroke's work is now garbage
    task = Task {                // inherits @MainActor from self
      guard let r = try? await api.search(q), !Task.isCancelled else { return }
      results = r                // already on the main actor
    }
