// Reentrancy gotcha — the classic duplicate-request bug
actor ImageCache {
  private var cached: [URL: UIImage] = [:]
  private var inFlight: [URL: Task<UIImage, Error>] = [:]

  func image(at url: URL) async throws -> UIImage {
    if let hit = cached[url] { return hit }
    // ❌ Without the inFlight map, ten concurrent callers all miss the cache
    //    here and all start their own download: the actor is reentrant, so
    //    each one gets to run before any of them finishes.
    if let running = inFlight[url] { return try await running.value }

    let task = Task { try await download(url) }
    inFlight[url] = task
    defer { inFlight[url] = nil }
    let image = try await task.value
    cached[url] = image
    return image
  }
}

