@MainActor
final class FeedModel {
  var rows: [Row] = []

  func reload() async throws {
    let data = try await api.fetch()        // suspends, resumes back on the main actor
    rows = try await parse(data)            // stays on the main actor — it is cheap
    rows = try await heavyParse(data)       // this one leaves, because it is marked below
  }
}

// Inherits the caller's isolation: called from FeedModel it runs on the main actor.
// This is what plain `nonisolated async` means once NonisolatedNonsendingByDefault is on.
nonisolated(nonsending) func parse(_ data: Data) async throws -> [Row] {
  try JSONDecoder().decode([Row].self, from: data)
}

// Always hops to the concurrent pool, whoever calls it.
// Parameters and results cross a concurrency boundary, so they must be Sendable.
@concurrent func heavyParse(_ data: Data) async throws -> [Row] {
  let rows = try JSONDecoder().decode([Row].self, from: data)
  return rows.sorted { $0.rank > $1.rank }   // CPU-bound: keep it off the main actor
}

// Function types carry the same distinction
let a: nonisolated(nonsending) (Data) async throws -> [Row] = parse
let b: @concurrent (Data) async throws -> [Row] = heavyParse

func downloadAll(_ urls: [URL], limit: Int = 5) async throws -> [URL: Data] {
  try await withThrowingTaskGroup(of: (URL, Data).self) { group in
    var pending = urls.makeIterator()
    var results: [URL: Data] = [:]

    // Seed the window
    for _ in 0..<min(limit, urls.count) {
      guard let url = pending.next() else { break }
      group.addTask { (url, try await download(url)) }
    }

    // One in, one out — the group never holds more than `limit` children
    while let (url, data) = try await group.next() {
      results[url] = data
      if let next = pending.next() {
        group.addTask { (next, try await download(next)) }
      }
    }
    return results
  }
}

// Unbounded and unstructured: 500 live tasks, no back-pressure, no cancellation
func downloadAllBad(_ urls: [URL]) {
  for url in urls { Task { _ = try? await download(url) } }
}

// If you need input order back, key by index and sort at the end
func ordered(_ urls: [URL]) async throws -> [Data] {
  var byIndex: [Int: Data] = [:]
  try await withThrowingTaskGroup(of: (Int, Data).self) { group in
    for (i, url) in urls.enumerated() { group.addTask { (i, try await download(url)) } }
    for try await (i, data) in group { byIndex[i] = data }
  }
  return urls.indices.compactMap { byIndex[$0] }
}

