// Sequential, despite looking parallel: each iteration awaits before the next starts
func serialByAccident(_ ids: [String]) async throws -> [Avatar] {
  var out: [Avatar] = []
  for id in ids {
    async let avatar = api.avatar(id: id)
    out.append(try await avatar)
  }
  return out
}

// Runtime-sized fan-out belongs in a group
func parallel(_ ids: [String]) async throws -> [Avatar] {
  try await withThrowingTaskGroup(of: Avatar.self) { group in
    for id in ids { group.addTask { try await api.avatar(id: id) } }
    return try await group.reduce(into: []) { $0.append($1) }
  }
}

struct TimedOut: Error {}

func withTimeout<T: Sendable>(
  _ duration: Duration,
  clock: any Clock<Duration> = ContinuousClock(),
  operation: @escaping @Sendable () async throws -> T
) async throws -> T {
  try await withThrowingTaskGroup(of: T.self) { group in
    group.addTask { try await operation() }
    group.addTask {
      try await Task.sleep(for: duration, clock: clock)
      throw TimedOut()
    }
    guard let winner = try await group.next() else { throw TimedOut() }
    // Without this, returning here awaits the sleeper: every call takes 5s
    group.cancelAll()
    return winner
  }
}

