// Drifts: each period is 30s PLUS however long the fetch and the wake-up took
func pollBad() async throws {
  while !Task.isCancelled {
    try await refresh()
    try await Task.sleep(for: .seconds(30))
  }
}

// Fixed period: the deadline advances on a grid, so a slow fetch is absorbed
func poll(clock: any Clock<Duration> = ContinuousClock()) async throws {
  var next = clock.now
  while !Task.isCancelled {
    try await refresh()
    next = next.advanced(by: .seconds(30))
    // tolerance lets the OS coalesce this wake-up with other timers
    try await Task.sleep(until: next, tolerance: .seconds(2), clock: clock)
  }
}

