enum RequestContext {
  @TaskLocal static var traceID: String?
  @TaskLocal static var user: User?
}

func log(_ message: String) {
  print("[\(RequestContext.traceID ?? "-")] \(message)")
}

// Bind once at the edge; every layer underneath sees it with no parameter
func handle(_ request: Request) async throws -> Response {
  try await RequestContext.$traceID.withValue(UUID().uuidString) {
    try await loadProfile(request.userID)
  }
}

func loadProfile(_ id: String) async throws -> Response {
  log("loading profile")                  // same trace ID, ten layers deep
  async let posts = loadPosts(id)         // child tasks inherit the binding
  async let badges = loadBadges(id)
  return try await Response(posts: posts, badges: badges)
}

// Task inherits the current values; Task.detached starts empty
RequestContext.$traceID.withValue("abc") {
  Task { log("abc") }
  Task.detached { log("-") }              // inherits nothing
}

// Leaving the task system loses the binding — re-bind on the way back in
func bridge(_ id: String, _ body: @escaping @Sendable () -> Void) {
  legacyQueue.async {
    RequestContext.$traceID.withValue(id) { body() }
  }
}

