await warm(cache, from: entries)

// The actor is released at an await, so downloads here are NOT serialized —
// and the state you checked before the await can be stale after it
extension ImageCache {
  func image(for key: String) async throws -> Data {
    if let hit = storage[key] { return hit }
    let data = try await download(key)     // actor is free: other calls interleave
    if let raced = storage[key] { return raced }   // re-check after suspension
    storage[key] = data
    return data
  }
}
